typedef unsigned char uint8;
typedef float rational_t;

class color32 {
public:
    union {
        struct { uint8 b, g, r, a; } c;
        unsigned int i;
    };
    uint8 get_red() const { return c.r; }
    uint8 get_green() const { return c.g; }
    uint8 get_blue() const { return c.b; }
};

class beam;
class beam_effect_type {
public:
    virtual ~beam_effect_type();
    virtual void apply_target_vals(beam *the_beam) = 0;
    virtual void apply_delta_vals(beam *the_beam, float t) = 0;
    virtual void reverse() = 0;
    virtual beam_effect_type *make_instance() = 0;
};

class beam_effect_color : public beam_effect_type {
public:
    virtual ~beam_effect_color();
    virtual void apply_target_vals(beam *the_beam);
    virtual void apply_delta_vals(beam *the_beam, float t);
    virtual void reverse();
    uint8 start[3];
    uint8 target[3];
    rational_t delta[3];
    rational_t curr[3];
    virtual beam_effect_type *make_instance();
};

class beam_effect {
    enum effect_mode {
        EFFECT_DEAD = 0,
        EFFECT_DELAY = 1,
        EFFECT_ACTIVE = 2,
        EFFECT_INVERTED_DELAY = -1,
        EFFECT_INVERTED_ACTIVE = -2
    };
    beam *my_beam;
    beam_effect_type *effect;
    unsigned short id;
    char mode;
    rational_t timer;
    rational_t loop_delay;
    rational_t duration;
public:
    virtual ~beam_effect();
    virtual void dump();
    virtual void set_active();
    virtual void set_delaying();
    virtual void set_color_delta(const color32&, const color32&, rational_t, rational_t, rational_t, bool) __asm__("set_color_delta__11beam_effectRC7color32T1fffb");
};

void beam_effect::set_color_delta(const color32& start_color, const color32& end_color, rational_t the_duration, rational_t the_delay, rational_t the_loop_delay, bool invert_loop)
{
  dump();

  effect = new beam_effect_color();
  beam_effect_color *color_effect = (beam_effect_color *)effect;

  color_effect->start[0] = start_color.get_red();
  color_effect->target[0] = end_color.get_red();

  color_effect->start[1] = start_color.get_green();
  color_effect->target[1] = end_color.get_green();

  color_effect->start[2] = start_color.get_blue();
  color_effect->target[2] = end_color.get_blue();

  duration = the_duration;

  if(duration > 0)
  {
    color_effect->delta[0] = (color_effect->target[0] - color_effect->start[0]) / duration;
    color_effect->delta[1] = (color_effect->target[1] - color_effect->start[1]) / duration;
    color_effect->delta[2] = (color_effect->target[2] - color_effect->start[2]) / duration;
  }

  if(invert_loop)
    mode = EFFECT_INVERTED_DELAY;
  else
    mode = EFFECT_DELAY;

  loop_delay = the_loop_delay;
  timer = the_delay;
}
